    const sc = [[140, 2000, 300, 17], [140, 2000, -300, 16], [150, 2000, 60, 9], [110, 2000, 200, 20], [180, 2000, 200, 12]], fs = sc.map(([V, alt, dh]) => altStep(fight, V, alt, dh)), bs = sc.map(([V, alt, dh]) => altStep(base, V, alt, dh));
